import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

function AuthPage() {
  const navigate = useNavigate();
  const [username, setUsername] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [loginIdentifier, setLoginIdentifier] = useState(""); // username or email 
  const [message, setMessage] = useState("");
  const [googleUser, setGoogleUser] = useState(null);
  const [currentPage, setCurrentPage] = useState("login"); // "login" or "register"
  const [showForgot, setShowForgot] = useState(false);
  const [resetStep, setResetStep] = useState(1); // 1: send code, 2: enter code + new pw
  const [resetEmail, setResetEmail] = useState("");
  const [resetCode, setResetCode] = useState("");
  const [resetNewPassword, setResetNewPassword] = useState("");
  const [resetConfirmNewPassword, setResetConfirmNewPassword] = useState("");
  
  // Registration extras
  const [role, setRole] = useState("employee"); // 'employee' or 'manager'
  const [fullName, setFullName] = useState("");
  const [department, setDepartment] = useState("");
  const [managerId, setManagerId] = useState("");
  const [designation, setDesignation] = useState("associate");
  const [workCity, setWorkCity] = useState("");
  const [employeeId, setEmployeeId] = useState("");
  
  // Loading states
  const [isLoading, setIsLoading] = useState(false);
  const [isLoginLoading, setIsLoginLoading] = useState(false);
  const [isRegisterLoading, setIsRegisterLoading] = useState(false);
  const [isResetLoading, setIsResetLoading] = useState(false);

  // Check if user is already logged in
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) {
      navigate("/profile");
    }
  }, [navigate]);

  // Validation helpers
  const isEmailValid = (value) => /[^\s@]+@[^\s@]+\.[^\s@]+/.test(value);
  const passHasLen = password.length >= 8;
  const passHasUpper = /[A-Z]/.test(password);
  const passHasLower = /[a-z]/.test(password);
  const passHasNumber = /\d/.test(password);
  const passHasSpecial = /[^A-Za-z0-9]/.test(password);
  const isPasswordStrong = passHasLen && passHasUpper && passHasLower && passHasNumber && passHasSpecial;

  // Reset password validators
  const rPassHasLen = resetNewPassword.length >= 8;
  const rPassHasUpper = /[A-Z]/.test(resetNewPassword);
  const rPassHasLower = /[a-z]/.test(resetNewPassword);
  const rPassHasNumber = /\d/.test(resetNewPassword);
  const rPassHasSpecial = /[^A-Za-z0-9]/.test(resetNewPassword);
  const isResetPasswordStrong = rPassHasLen && rPassHasUpper && rPassHasLower && rPassHasNumber && rPassHasSpecial;

  // Utilities to normalize messages (objects, arrays, error shapes) to string
  const toMessageText = (value) => {
    if (value == null || value === undefined) return "";
    if (typeof value === "string") return value;
    if (typeof value === "number" || typeof value === "boolean") return String(value);
    
    try {
      if (typeof value === "object") {
        if (typeof value.detail === "string") return value.detail;
        if (typeof value.message === "string") return value.message;
        // FastAPI/DRF validation errors can be arrays or objects
        if (Array.isArray(value) && value.length > 0) {
          // Try to surface the first human-friendly message
          const first = value[0];
          if (typeof first === "string") return first;
          if (first && typeof first.msg === "string") return first.msg;
        }
      }
      return JSON.stringify(value);
    } catch {
      return String(value || "");
    }
  };

  // Show success message with auto-clear
  const showSuccessMessage = (msg) => {
    const text = toMessageText(msg) || "Success";
    setMessage(text);
    setTimeout(() => setMessage(""), 5000);
  };

  // Show error message with auto-clear
  const showErrorMessage = (msg) => {
    const text = toMessageText(msg) || "An error occurred";
    setMessage(text);
    setTimeout(() => setMessage(""), 7000);
  };

  const register = async () => {
    if (!username || !email || !password || !confirmPassword) {
      showErrorMessage("All fields are required");
      return;
    }

    if (!isEmailValid(email)) {
      showErrorMessage("Please enter a valid email address");
      return;
    }

    if (password !== confirmPassword) {
      showErrorMessage("Passwords do not match");
      return;
    }

    if (!isPasswordStrong) {
      showErrorMessage("Please meet the password requirements below");
      return;
    }

    setIsRegisterLoading(true);
    try {
      await axios.post("http://localhost:8000/register", {
        username,
        email,
        password,
        role,
        full_name: fullName,
        department,
        manager_id: managerId || null,
        designation,
        work_city: workCity,
        employee_id: employeeId || null,
      });
      
      // Show success message and redirect to login page
      showSuccessMessage("Registration successful! Please login with your credentials.");
      setCurrentPage("login");
      
      // Clear form fields
      setUsername("");
      setEmail("");
      setPassword("");
      setConfirmPassword("");
      
    } catch (err) {
      showErrorMessage(err.response?.data?.detail || "Error registering");
    } finally {
      setIsRegisterLoading(false);
    }
  };

  const login = async () => {
    if (!loginIdentifier || !password) {
      showErrorMessage("Please enter your username or email and password");
      return;
    }

    setIsLoginLoading(true);
    try {
      const payload = loginIdentifier.includes("@")
        ? { email: loginIdentifier, password }
        : { username: loginIdentifier, password };
      const res = await axios.post("http://localhost:8000/login", payload);
      
      // Save token
      const { access_token, message: resMessage } = res.data;
      if (!access_token) {
        throw new Error("Empty access token received");
      }
      localStorage.setItem("token", access_token);
      showSuccessMessage(resMessage);
      
      // Fetch profile to determine role and route accordingly
      const profileRes = await axios.get("http://localhost:8000/profile", {
        headers: { Authorization: `Bearer ${access_token}` }
      });
      const role = profileRes?.data?.role || "employee";
      
      if (role === "manager") {
        navigate("/team-bills");
      } else {
        navigate("/profile");
      }
    } catch (err) {
      const detail = err.response?.data?.detail || err.message || "Error logging in";
      showErrorMessage(detail);
      // Ensure no stale/empty token blocks routing
      localStorage.removeItem("token");
    } finally {
      setIsLoginLoading(false);
    }
  };

  // Forgot password flow
  const sendResetCode = async () => {
    if (!resetEmail || !isEmailValid(resetEmail)) {
      showErrorMessage("Enter a valid email to receive a code");
      return;
    }
    
    setIsResetLoading(true);
    try {
      await axios.post("http://localhost:8000/forgot-password", { email: resetEmail });
      showSuccessMessage("If the email exists, a reset code has been sent. Check your inbox.");
      setResetStep(2);
    } catch (err) {
      // Always generic
      showSuccessMessage("If the email exists, a reset code has been sent. Check your inbox.");
      setResetStep(2);
    } finally {
      setIsResetLoading(false);
    }
  };

  const resetPassword = async () => {
    if (!resetCode || !resetNewPassword || !resetConfirmNewPassword) {
      showErrorMessage("All fields are required");
      return;
    }
    if (resetNewPassword !== resetConfirmNewPassword) {
      showErrorMessage("Passwords do not match");
      return;
    }
    if (!isResetPasswordStrong) {
      showErrorMessage("Please meet the password requirements below");
      return;
    }
    
    setIsResetLoading(true);
    try {
      await axios.post("http://localhost:8000/reset-password", {
        email: resetEmail,
        code: resetCode,
        new_password: resetNewPassword,
      });
      showSuccessMessage("Password reset successful. Please login with your new password.");
      // Reset forgot state and go back to login
      setShowForgot(false);
      setCurrentPage("login");
      setLoginIdentifier(resetEmail); // prefill email
      setResetEmail("");
      setResetCode("");
      setResetNewPassword("");
      setResetConfirmNewPassword("");
    } catch (err) {
      showErrorMessage(err.response?.data?.detail || "Unable to reset password. Check your code and try again.");
    } finally {
      setIsResetLoading(false);
    }
  };

  // Handle Google Sign-In response
  const handleGoogleResponse = async (response) => {
    setIsLoading(true);
    try {
      const credential = response.credential;
      const payload = JSON.parse(atob(credential.split('.')[1]));
      
      // Extract user info from the JWT payload
      const googleUserInfo = {
        email: payload.email,
        name: payload.name
      };
      
      setGoogleUser(googleUserInfo);
      
      // Send to backend
      const res = await axios.post("http://localhost:8000/google-login", googleUserInfo);
      
      // Save token
      const { access_token, message: resMessage } = res.data;
      localStorage.setItem("token", access_token);
      showSuccessMessage(resMessage);
      
      // Redirect to profile page
      navigate("/profile");
    } catch (err) {
      showErrorMessage(err.response?.data?.detail || "Error with Google Sign-In");
    } finally {
      setIsLoading(false);
    }
  };

  // Initialize Google Sign-In
  useEffect(() => {
    // Fetch Google Client ID from backend
    const fetchGoogleClientId = async () => {
      try {
        const response = await axios.get("http://localhost:8000/google-client-id");
        const clientId = response.data.client_id;
        
        if (window.google && clientId) {
          window.google.accounts.id.initialize({
            client_id: clientId,
            callback: handleGoogleResponse,
          });

          window.google.accounts.id.renderButton(
            document.getElementById("google-signin"),
            { theme: "outline", size: "large", text: "signin_with", shape: "rectangular" }
          );
        }
      } catch (err) {
        console.error("Error fetching Google Client ID:", err);
        showErrorMessage("Error initializing Google Sign-In");
      }
    };

    fetchGoogleClientId();
  }, []);

  // Determine message class based on content (robust against non-strings)
  const getMessageClass = () => {
    if (!message) return "";
    const text = typeof message === "string" ? message : toMessageText(message);
    // Ensure text is always a string before calling toLowerCase
    const safeText = typeof text === "string" ? text : String(text || "");
    const lower = safeText.toLowerCase();
    return (lower.includes("error") || lower.includes("fail") || lower.includes("invalid"))
      ? "message error"
      : "message success";
  };

  // Clear message when switching pages
  const switchToPage = (page) => {
    setCurrentPage(page);
    setMessage("");
    setUsername("");
    setEmail("");
    setPassword("");
    setConfirmPassword("");
    setLoginIdentifier("");
    setShowForgot(false);
    setResetStep(1);
    setResetEmail("");
    setResetCode("");
    setResetNewPassword("");
    setResetConfirmNewPassword("");
    setRole("employee");
    setFullName("");
    setDepartment("");
    setManagerId("");
    setDesignation("associate");
    setWorkCity("");
    setEmployeeId("");
  };

  // Enhanced loading spinner component
  const LoadingSpinner = () => (
    <div style={{
      display: 'inline-flex',
      alignItems: 'center',
      gap: '8px'
    }}>
      <div style={{
        width: '20px',
        height: '20px',
        border: '3px solid rgba(255, 255, 255, 0.3)',
        borderTop: '3px solid white',
        borderRadius: '50%',
        animation: 'spin 0.8s linear infinite'
      }}></div>
      <div style={{
        display: 'flex',
        gap: '3px'
      }}>
        <div style={{
          width: '4px',
          height: '4px',
          backgroundColor: 'rgba(255, 255, 255, 0.8)',
          borderRadius: '50%',
          animation: 'pulse 1.4s ease-in-out infinite'
        }}></div>
        <div style={{
          width: '4px',
          height: '4px',
          backgroundColor: 'rgba(255, 255, 255, 0.8)',
          borderRadius: '50%',
          animation: 'pulse 1.4s ease-in-out 0.2s infinite'
        }}></div>
        <div style={{
          width: '4px',
          height: '4px',
          backgroundColor: 'rgba(255, 255, 255, 0.8)',
          borderRadius: '50%',
          animation: 'pulse 1.4s ease-in-out 0.4s infinite'
        }}></div>
      </div>
    </div>
  );

  return (
    <>
      {/* Enhanced CSS Animations */}
      <style>
        {`
          @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
          }
          
          @keyframes pulse {
            0%, 100% { 
              opacity: 0.4;
              transform: scale(0.8);
            }
            50% { 
              opacity: 1;
              transform: scale(1.2);
            }
          }
          
          @keyframes slideInUp {
            from {
              opacity: 0;
              transform: translateY(30px);
            }
            to {
              opacity: 1;
              transform: translateY(0);
            }
          }
          
          @keyframes fadeInScale {
            from {
              opacity: 0;
              transform: scale(0.95);
            }
            to {
              opacity: 1;
              transform: scale(1);
            }
          }

          @keyframes float {
            0%, 100% { transform: translateY(0px); }
            50% { transform: translateY(-10px); }
          }

          @keyframes shimmer {
            0% { background-position: 200% 0; }
            100% { background-position: -200% 0; }
          }
        `}
      </style>
      
      <div className="modern-auth-container">
        {/* Background Decorative Elements */}
        <div className="auth-bg-decoration">
          <div className="floating-shape shape-1"></div>
          <div className="floating-shape shape-2"></div>
          <div className="floating-shape shape-3"></div>
          <div className="floating-shape shape-4"></div>
        </div>

        {/* Main Content */}
        <div className="auth-content">
          {/* Header Section */}
          <div className="auth-header">
            <div className="brand-logo">
              <div className="logo-icon">🚀</div>
              <h1 className="brand-title">PRixGEn</h1>
            </div>
            <p className="brand-subtitle">AI-Powered Expense Management Platform</p>
          </div>

          {/* Enhanced Page Navigation */}
          <div className="modern-tabs">
            <button 
              className={`modern-tab ${currentPage === "login" ? "active" : ""}`}
              onClick={() => switchToPage("login")}
              disabled={isLoading}
            >
              <span className="tab-icon">🔐</span>
              <span className="tab-text">Sign In</span>
            </button>
            <button 
              className={`modern-tab ${currentPage === "register" ? "active" : ""}`}
              onClick={() => switchToPage("register")}
              disabled={isLoading}
            >
              <span className="tab-icon">✨</span>
              <span className="tab-text">Create Account</span>
            </button>
          </div>

          {currentPage === "login" ? (
            // Login or Forgot Password Page
            <div className="auth-form-container">
              {!showForgot ? (
                <>
                  <div className="form-header">
                    <h2 className="form-title">Welcome Back!</h2>
                    <p className="form-subtitle">Sign in to your account to continue</p>
                  </div>
                  
                  <form className="modern-form" onSubmit={(e) => { e.preventDefault(); login(); }}>
                    <div className="form-group">
                      <label className="form-label">
                        <span className="label-icon">👤</span>
                        Username or Email
                      </label>
                      <input
                        className="modern-input"
                        placeholder="Enter your username or email"
                        value={loginIdentifier}
                        onChange={(e) => setLoginIdentifier(e.target.value)}
                        disabled={isLoginLoading}
                      />
                    </div>
                    
                    <div className="form-group">
                      <label className="form-label">
                        <span className="label-icon">🔒</span>
                        Password
                      </label>
                      <input
                        className="modern-input"
                        type="password"
                        placeholder="Enter your password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        disabled={isLoginLoading}
                      />
                    </div>
                    
                    <button 
                      type="submit"
                      className="modern-btn primary"
                      disabled={isLoginLoading}
                    >
                      {isLoginLoading ? (
                        <div className="btn-content">
                          <LoadingSpinner />
                          <span>Signing In...</span>
                        </div>
                      ) : (
                        <div className="btn-content">
                          <span className="btn-icon">🚀</span>
                          <span>Sign In</span>
                        </div>
                      )}
                    </button>
                  </form>

                  <div className="form-footer">
                    <button 
                      className="forgot-password-btn"
                      onClick={() => { setShowForgot(true); setMessage(""); }}
                      disabled={isLoading}
                    >
                      🔑 Forgot your password?
                    </button>
                  </div>
                  
                  <div className="divider">
                    <span className="divider-text">or continue with</span>
                  </div>
                  
                  <div className="google-signin-container">
                    <div id="google-signin"></div>
                  </div>
                </>
              ) : (
                <>
                  <div className="form-header">
                    <h2 className="form-title">Reset Password</h2>
                    <p className="form-subtitle">
                      {resetStep === 1 
                        ? "Enter your email to receive a reset code" 
                        : "Enter the code and set a new password"
                      }
                    </p>
                  </div>

                  {resetStep === 1 ? (
                    <form className="modern-form" onSubmit={(e) => { e.preventDefault(); sendResetCode(); }}>
                      <div className="form-group">
                        <label className="form-label">
                          <span className="label-icon">📧</span>
                          Email Address
                        </label>
                        <input
                          className="modern-input"
                          type="email"
                          placeholder="Enter your email address"
                          value={resetEmail}
                          onChange={(e) => setResetEmail(e.target.value)}
                          disabled={isResetLoading}
                        />
                      </div>
                      
                      <button 
                        type="submit"
                        className="modern-btn primary"
                        disabled={isResetLoading}
                      >
                        {isResetLoading ? (
                          <div className="btn-content">
                            <LoadingSpinner />
                            <span>Sending Code...</span>
                          </div>
                        ) : (
                          <div className="btn-content">
                            <span className="btn-icon">📤</span>
                            <span>Send Reset Code</span>
                          </div>
                        )}
                      </button>
                    </form>
                  ) : (
                    <form className="modern-form" onSubmit={(e) => { e.preventDefault(); resetPassword(); }}>
                      <div className="form-group">
                        <label className="form-label">
                          <span className="label-icon">🔢</span>
                          Verification Code
                        </label>
                        <input
                          className="modern-input"
                          placeholder="Enter the 6-digit code"
                          value={resetCode}
                          onChange={(e) => setResetCode(e.target.value)}
                          disabled={isResetLoading}
                        />
                      </div>
                      
                      <div className="form-group">
                        <label className="form-label">
                          <span className="label-icon">🔒</span>
                          New Password
                        </label>
                        <input
                          className="modern-input"
                          type="password"
                          placeholder="Create a new password"
                          value={resetNewPassword}
                          onChange={(e) => setResetNewPassword(e.target.value)}
                          disabled={isResetLoading}
                        />
                        <div className="password-requirements">
                          <div className={`req-item ${rPassHasLen ? 'valid' : 'invalid'}`}>
                            <span className="req-icon">{rPassHasLen ? '✓' : '○'}</span>
                            At least 8 characters
                          </div>
                          <div className={`req-item ${rPassHasUpper ? 'valid' : 'invalid'}`}>
                            <span className="req-icon">{rPassHasUpper ? '✓' : '○'}</span>
                            One uppercase letter
                          </div>
                          <div className={`req-item ${rPassHasLower ? 'valid' : 'invalid'}`}>
                            <span className="req-icon">{rPassHasLower ? '✓' : '○'}</span>
                            One lowercase letter
                          </div>
                          <div className={`req-item ${rPassHasNumber ? 'valid' : 'invalid'}`}>
                            <span className="req-icon">{rPassHasNumber ? '✓' : '○'}</span>
                            One number
                          </div>
                          <div className={`req-item ${rPassHasSpecial ? 'valid' : 'invalid'}`}>
                            <span className="req-icon">{rPassHasSpecial ? '✓' : '○'}</span>
                            One special character
                          </div>
                        </div>
                      </div>
                      
                      <div className="form-group">
                        <label className="form-label">
                          <span className="label-icon">🔒</span>
                          Confirm New Password
                        </label>
                        <input
                          className="modern-input"
                          type="password"
                          placeholder="Confirm your new password"
                          value={resetConfirmNewPassword}
                          onChange={(e) => setResetConfirmNewPassword(e.target.value)}
                          disabled={isResetLoading}
                        />
                      </div>
                      
                      <button 
                        type="submit"
                        className="modern-btn primary"
                        disabled={isResetLoading}
                      >
                        {isResetLoading ? (
                          <div className="btn-content">
                            <LoadingSpinner />
                            <span>Resetting Password...</span>
                          </div>
                        ) : (
                          <div className="btn-content">
                            <span className="btn-icon">🔄</span>
                            <span>Reset Password</span>
                          </div>
                        )}
                      </button>
                    </form>
                  )}

                  <div className="form-footer">
                    <button 
                      className="back-to-login-btn"
                      onClick={() => { setShowForgot(false); setResetStep(1); }}
                      disabled={isLoading}
                    >
                      ← Back to Sign In
                    </button>
                  </div>
                </>
              )}
            </div>
          ) : (
            // Registration Page
            <div className="auth-form-container">
              <div className="form-header">
                <h2 className="form-title">Create Your Account</h2>
                <p className="form-subtitle">Join us and start managing expenses intelligently</p>
              </div>
              
              <form className="modern-form" onSubmit={(e) => { e.preventDefault(); register(); }}>
                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label">
                      <span className="label-icon">👤</span>
                      Username
                    </label>
                    <input
                      className="modern-input"
                      placeholder="Choose a username"
                      value={username}
                      onChange={(e) => setUsername(e.target.value)}
                      disabled={isRegisterLoading}
                    />
                  </div>

                  <div className="form-group">
                    <label className="form-label">
                      <span className="label-icon">📧</span>
                      Email Address
                    </label>
                    <input
                      className="modern-input"
                      type="email"
                      placeholder="Enter your email"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      disabled={isRegisterLoading}
                    />
                  </div>
                </div>

                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label">
                      <span className="label-icon">👔</span>
                      Role
                    </label>
                    <select
                      className="modern-input"
                      value={role}
                      onChange={(e) => setRole(e.target.value)}
                      disabled={isRegisterLoading}
                    >
                      <option value="employee">Employee</option>
                      <option value="manager">Manager</option>
                    </select>
                  </div>

                  <div className="form-group">
                    <label className="form-label">
                      <span className="label-icon">🏢</span>
                      Department
                    </label>
                    <input
                      className="modern-input"
                      placeholder="e.g., Sales, Engineering"
                      value={department}
                      onChange={(e) => setDepartment(e.target.value)}
                      disabled={isRegisterLoading}
                    />
                  </div>
                </div>

                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label">
                      <span className="label-icon">📍</span>
                      Work City
                    </label>
                    <input
                      className="modern-input"
                      placeholder="e.g., Mumbai, Delhi, Bangalore"
                      value={workCity}
                      onChange={(e) => setWorkCity(e.target.value)}
                      disabled={isRegisterLoading}
                    />
                  </div>

                  <div className="form-group">
                    <label className="form-label">
                      <span className="label-icon">🆔</span>
                      Employee ID
                    </label>
                    <input
                      className="modern-input"
                      placeholder="Company employee ID"
                      value={employeeId}
                      onChange={(e) => setEmployeeId(e.target.value)}
                      disabled={isRegisterLoading}
                    />
                  </div>
                </div>

                {/* Designation field for employees */}
                {role === "employee" && (
                  <div className="form-group">
                    <label className="form-label">
                      <span className="label-icon">⭐</span>
                      Designation
                    </label>
                    <select
                      className="modern-input"
                      value={designation}
                      onChange={(e) => setDesignation(e.target.value)}
                      disabled={isRegisterLoading}
                    >
                      <option value="intern">Intern</option>
                      <option value="associate">Associate</option>
                      <option value="senior_associate">Senior Associate</option>
                      <option value="team_lead">Team Lead</option>
                      <option value="senior_team_lead">Senior Team Lead</option>
                    </select>
                  </div>
                )}

                {/* Manager ID field for employees */}
                {role === "employee" && (
                  <div className="form-group">
                    <label className="form-label">
                      <span className="label-icon">👨‍💼</span>
                      Manager ID (Optional)
                    </label>
                    <input
                      className="modern-input"
                      placeholder="Your manager's user ID"
                      value={managerId}
                      onChange={(e) => setManagerId(e.target.value)}
                      disabled={isRegisterLoading}
                    />
                  </div>
                )}

                <div className="form-group">
                  <label className="form-label">
                    <span className="label-icon">🔒</span>
                    Password
                  </label>
                  <input
                    className="modern-input"
                    type="password"
                    placeholder="Create a strong password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    disabled={isRegisterLoading}
                  />
                  <div className="password-requirements">
                    <div className={`req-item ${passHasLen ? 'valid' : 'invalid'}`}>
                      <span className="req-icon">{passHasLen ? '✓' : '○'}</span>
                      At least 8 characters
                    </div>
                    <div className={`req-item ${passHasUpper ? 'valid' : 'invalid'}`}>
                      <span className="req-icon">{passHasUpper ? '✓' : '○'}</span>
                      One uppercase letter
                    </div>
                    <div className={`req-item ${passHasLower ? 'valid' : 'invalid'}`}>
                      <span className="req-icon">{passHasLower ? '✓' : '○'}</span>
                      One lowercase letter
                    </div>
                    <div className={`req-item ${passHasNumber ? 'valid' : 'invalid'}`}>
                      <span className="req-icon">{passHasNumber ? '✓' : '○'}</span>
                      One number
                    </div>
                    <div className={`req-item ${passHasSpecial ? 'valid' : 'invalid'}`}>
                      <span className="req-icon">{passHasSpecial ? '✓' : '○'}</span>
                      One special character
                    </div>
                  </div>
                </div>

                <div className="form-group">
                  <label className="form-label">
                    <span className="label-icon">🔒</span>
                    Confirm Password
                  </label>
                  <input
                    className="modern-input"
                    type="password"
                    placeholder="Confirm your password"
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    disabled={isRegisterLoading}
                  />
                </div>
                
                <button 
                  type="submit"
                  className="modern-btn primary"
                  disabled={isRegisterLoading}
                >
                  {isRegisterLoading ? (
                    <div className="btn-content">
                      <LoadingSpinner />
                      <span>Creating Account...</span>
                    </div>
                  ) : (
                    <div className="btn-content">
                      <span className="btn-icon">✨</span>
                      <span>Create Account</span>
                    </div>
                  )}
                </button>
              </form>

              <div className="form-footer">
                <p className="footer-text">
                  Already have an account?{" "}
                  <button 
                    className="switch-mode-btn"
                    onClick={() => switchToPage("login")}
                    disabled={isLoading}
                  >
                    Sign in here
                  </button>
                </p>
              </div>
            </div>
          )}

          {/* Enhanced Message Display */}
          {message && (
            <div className={`modern-message ${getMessageClass()}`}>
              <div className="message-content">
                <span className="message-icon">
                  {message.toLowerCase().includes('error') || message.toLowerCase().includes('fail') ? '⚠️' : '✅'}
                </span>
                <span className="message-text">{message}</span>
              </div>
            </div>
          )}

          {/* Footer */}
          <div className="auth-footer">
            <p className="footer-text">
              By continuing, you agree to our Terms of Service and Privacy Policy
            </p>
          </div>
        </div>
      </div>
    </>
  );
}

export default AuthPage;
